class ApiError(Exception):
    """An error answer: HTTP status, the stable reason (API_KEY_INVALID, RATE_LIMIT_EXCEEDED...) and Retry-After seconds."""

    def __init__(self, status: int, reason: Optional[str], message: str, retry_after: Optional[float], body: Any):
        super().__init__(message)
        self.status = status
        self.reason = reason
        self.retry_after = retry_after
        self.body = body


class Client:
    """The N-Ways Maps Platform API. `Client(api_key="nw_...")`."""

    def __init__(self, api_key: str, base_url: str = DEFAULT_BASE_URL, timeout: float = 10.0, headers: Optional[Dict[str, str]] = None):
        self.api_key = api_key
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.headers = headers or {}

    def request(self, method: str, path: str, query: Optional[Dict[str, Any]] = None, body: Any = None, raw: bool = False) -> Any:
        """Sends one request; JSON in and out (bytes when raw)."""
        params = {}
        for k, v in (query or {}).items():
            if v is None or v == "":
                continue
            if isinstance(v, (list, tuple)):
                v = ",".join(str(x) for x in v)
            elif isinstance(v, bool):
                v = "true" if v else "false"
            params[k] = v
        url = self.base_url + path + ("?" + urllib.parse.urlencode(params) if params else "")
        headers = {"Accept": "application/json", "X-NWays-Api-Key": self.api_key, "User-Agent": f"nways-python/{__version__}", **self.headers}
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as res:
                payload = res.read()
                if raw:
                    return payload
                return json.loads(payload) if payload else None
        except urllib.error.HTTPError as e:
            text = e.read().decode("utf-8", "replace")
            try:
                parsed: Any = json.loads(text)
            except ValueError:
                parsed = text
            err = parsed.get("error") if isinstance(parsed, dict) else None
            env = err if isinstance(err, dict) else {}
            reason = env.get("reason") or (parsed.get("code") if isinstance(parsed, dict) else None)
            message = env.get("message") or (err if isinstance(err, str) else f"HTTP {e.code}")
            ra = e.headers.get("Retry-After")
            raise ApiError(e.code, reason, message, float(ra) if ra and ra.replace(".", "", 1).isdigit() else None, parsed) from None

    def get_style(self, style: str, *, lang: Optional[Literal["en", "fr", "pt"]] = None, format_: Optional[Literal["mvt"]] = None) -> "GetStyleResponse":
        """A hosted map style (one map load) (GET /maps/v1/styles/{style}.json)"""
        return self.request("GET", f"/maps/v1/styles/{urllib.parse.quote(str(style), safe='')}.json", {"lang": lang, "format": format_}, None)

    def get_tile_countries(self) -> "GetTileCountriesResponse":
        """The countries the map covers (GET /maps/v1/tiles/countries.json)"""
        return self.request("GET", f"/maps/v1/tiles/countries.json", {}, None)

    def get_tile_archive(self, tileset: str) -> Any:
        """Removed — whole-country archives aren't part of the platform (GET /maps/v1/tiles/{tileset}.pmtiles)"""
        return self.request("GET", f"/maps/v1/tiles/{urllib.parse.quote(str(tileset), safe='')}.pmtiles", {}, None)

    def get_tile(self, tileset: str, z: str, x: str, y: str) -> bytes:
        """One vector tile (GET /maps/v1/tiles/{tileset}/{z}/{x}/{y}.mvt)"""
        return self.request("GET", f"/maps/v1/tiles/{urllib.parse.quote(str(tileset), safe='')}/{urllib.parse.quote(str(z), safe='')}/{urllib.parse.quote(str(x), safe='')}/{urllib.parse.quote(str(y), safe='')}.mvt", {}, None, raw=True)

    def get_raster_tile(self, theme: str, z: str, x: str, y: str) -> bytes:
        """One picture tile (GET /maps/v1/tiles/raster/{theme}/{z}/{x}/{y}.png)"""
        return self.request("GET", f"/maps/v1/tiles/raster/{urllib.parse.quote(str(theme), safe='')}/{urllib.parse.quote(str(z), safe='')}/{urllib.parse.quote(str(x), safe='')}/{urllib.parse.quote(str(y), safe='')}.png", {}, None, raw=True)

    def get_glyphs(self, stack: str, range: str) -> bytes:
        """Font glyphs for map labels (free) (GET /maps/v1/fonts/{stack}/{range}.pbf)"""
        return self.request("GET", f"/maps/v1/fonts/{urllib.parse.quote(str(stack), safe='')}/{urllib.parse.quote(str(range), safe='')}.pbf", {}, None, raw=True)

    def get_static_map(self, *, center: Optional[str] = None, zoom: Optional[float] = None, size: Optional[str] = None, scale: Optional[int] = None, theme: Optional[Literal["light", "dark"]] = None, format_: Optional[Literal["png", "jpg"]] = None, markers: Optional[List[str]] = None, path: Optional[List[str]] = None, signature: Optional[str] = None) -> bytes:
        """A map image (GET /maps/v1/staticmap)"""
        return self.request("GET", f"/maps/v1/staticmap", {"center": center, "zoom": zoom, "size": size, "scale": scale, "theme": theme, "format": format_, "markers": markers, "path": path, "signature": signature}, None, raw=True)

    def geocode(self, *, q: str, near: Optional[str] = None, country: Optional[str] = None, limit: Optional[int] = None, validate: Optional[bool] = None, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "GeocodeResponse":
        """Search for places, addresses and codes (GET /maps/v1/geocode)"""
        return self.request("GET", f"/maps/v1/geocode", {"q": q, "near": near, "country": country, "limit": limit, "validate": validate, "lang": lang, "fields": fields}, None)

    def reverse_geocode(self, *, lat: float, lng: float, radius: Optional[float] = None, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "ReverseResponse":
        """What's at a point (GET /maps/v1/reverse)"""
        return self.request("GET", f"/maps/v1/reverse", {"lat": lat, "lng": lng, "radius": radius, "lang": lang, "fields": fields}, None)

    def get_code(self, code: str, *, type_: Optional[Literal["postcode", "ghanapost", "pluscode", "homecode"]] = None, near: Optional[str] = None, country: Optional[str] = None, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "CodeResponse":
        """Any code people write as an address (GET /maps/v1/codes/{code})"""
        return self.request("GET", f"/maps/v1/codes/{urllib.parse.quote(str(code), safe='')}", {"type": type_, "near": near, "country": country, "lang": lang, "fields": fields}, None)

    def get_codes(self, body: GetCodesRequest) -> "GetCodesResponse":
        """Up to 100 codes of any kind at once (POST /maps/v1/codes/batch)"""
        return self.request("POST", f"/maps/v1/codes/batch", {}, body)

    def get_postcode(self, code: str, *, fields: Optional[str] = None) -> "Postcode":
        """A NIPOST postcode (alias of /codes/{code}) (GET /maps/v1/postcodes/{code})"""
        return self.request("GET", f"/maps/v1/postcodes/{urllib.parse.quote(str(code), safe='')}", {"fields": fields}, None)

    def get_postcodes(self, body: GetPostcodesRequest, *, fields: Optional[str] = None) -> "GetPostcodesResponse":
        """Up to 100 NIPOST postcodes at once (alias of /codes/batch) (POST /maps/v1/postcodes/batch)"""
        return self.request("POST", f"/maps/v1/postcodes/batch", {"fields": fields}, body)

    def get_ghana_post(self, code: str, *, fields: Optional[str] = None) -> "SearchResult":
        """A GhanaPost GPS address (alias of /codes/{code}) (GET /maps/v1/ghanapost/{code})"""
        return self.request("GET", f"/maps/v1/ghanapost/{urllib.parse.quote(str(code), safe='')}", {"fields": fields}, None)

    def get_plus_code(self, code: str, *, near: Optional[str] = None, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "PlusCodeResponse":
        """A Plus Code's area and what's there (alias of /codes/{code}) (GET /maps/v1/pluscodes/{code})"""
        return self.request("GET", f"/maps/v1/pluscodes/{urllib.parse.quote(str(code), safe='')}", {"near": near, "lang": lang, "fields": fields}, None)

    def autocomplete(self, *, q: str, session: Optional[str] = None, near: Optional[str] = None, country: Optional[str] = None, types: Optional[str] = None, limit: Optional[int] = None, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "GeocodeResponse":
        """Suggestions as someone types (billed per session) (GET /maps/v1/autocomplete)"""
        return self.request("GET", f"/maps/v1/autocomplete", {"q": q, "session": session, "near": near, "country": country, "types": types, "limit": limit, "lang": lang, "fields": fields}, None)

    def autocomplete_select(self, *, session: str, id_: str, lang: Optional[Literal["en", "fr", "pt"]] = None, fields: Optional[str] = None) -> "SelectResponse":
        """The picked suggestion in full (part of the session) (GET /maps/v1/autocomplete/select)"""
        return self.request("GET", f"/maps/v1/autocomplete/select", {"session": session, "id": id_, "lang": lang, "fields": fields}, None)

